/**
 * The Gathering
 * -------------
 * The animals come to Noah two by two, clean and unclean, and he brings them into the ark. Stage: the ark door at dawn, a line of creatures coming up the ramp, birds and beasts, a man and his sons guiding them; the world's parade, arriving.
 *
 * Palette 0x1a2e10 → 0x0d1808 · light: dusk · hero: ark
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./noah-kit.js.
 */

import { THREE, createScene, house, ark, person, crowd } from './noah-kit.js';

const BG = 0x1a2e10;
const GROUND = 0x060a04;

export function build(group) {
    const W = createScene(group, { seed: 3096593960, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060a04, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 14, 0, -14, 1.0 + W.r() * 0.3, { mud: 0x0c1708 });

    /* hero: the ark riding the flood */
    ark(W, group, 0, 0.2, 0, 1.0, { ry: 0.25 });

    /* hero: the ark */
    ark(W, group, 0, 0.2, 0, 1.1, { ry: 0.2 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a2e10, ry: 0.36, s: 1.00 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 25, 70, 44, [0x1a2e10, 0x0d1808, 0x060a04, 0x8a6a44, 0x6a4a30, 0xc8b088]);

    return W.finish();
}

export default { build };
